mapper.delete:
DELETE FROM CLASS
WHERE CLASS_CODE = #{classCode}
  AND OPERATOR_CODE = #{authorCode}
  AND STATUS = '준비중'
  AND APPROVAL_STATUS = '작성중'
  AND APPROVAL_MEMO IS NULL

mapper.update:
UPDATE CLASS c
SET c.CATEGORY_CODE = #{categoryCode},
	c.NAME = #{classTitle},
	c.SINGLE_INTRODUCE = #{shortIntroduction},
	c.INTRODUCE = #{classIntroduction}
WHERE c.CLASS_CODE = #{classCode}
  AND c.OPERATOR_CODE = #{authorCode}
  AND c.STATUS IN ('모집중', '준비중')
  AND c.APPROVAL_STATUS = '승인'
  AND EXISTS (
	  SELECT 1 FROM CATEGORY ct
	  WHERE ct.CATEGORY_CODE = #{categoryCode}
	    AND ct.PARENTS_CATEGORY IS NOT NULL
  )

UPDATE CLASS
SET FINISH_INTRODUCE = #{resultDescription}
WHERE CLASS_CODE = #{classCode}
  AND OPERATOR_CODE = #{authorCode}
  AND STATUS IN ('모집중', '준비중')
  AND APPROVAL_STATUS = '승인'

mapper.delete:
DELETE FROM DETAIL_INFO
WHERE CLASS_CODE = #{classCode}
  AND CHARACTER = #{detailType}

mapper.insert:

	SELECT SEQ_DETAIL_INFO_CODE.NEXTVAL
	FROM DUAL

INSERT INTO DETAIL_INFO (DETAIL_INFO_CODE, CLASS_CODE, CHARACTER, INGREDIENTS)
VALUES (
	#{generatedCode}, #{classCode}, #{detailType}, #{content}
)

INSERT INTO CLASS_OFFERING_MAP (CLASS_OFFERING_CODE, CLASS_CODE)
SELECT CLASS_OFFERING_CODE, #{classCode}
FROM CLASS_OFFERING
WHERE CLASS_OFFERING_CODE = #{optionCode}
  AND USE_YN = 'Y'


	SELECT SEQ_CLASS_ADDITIONAL_INFO_CODE.NEXTVAL
	FROM DUAL

INSERT INTO CLASS_ADDITIONAL_INFO (
	ADDITIONAL_INFO_CODE, CLASS_CODE, ADDITIONAL_INFO_CONTENT
) VALUES (
	#{generatedCode}, #{classCode}, #{content}
)


	SELECT SEQ_TAG_CODE.NEXTVAL
	FROM DUAL

INSERT INTO TAG (TAG_CODE, CLASS_CODE, TAG_NAME)
VALUES (
	#{generatedCode}, #{classCode}, #{content}
)


	SELECT SEQ_CLASS_MATERIAL_CODE.NEXTVAL
	FROM DUAL

INSERT INTO CLASS_MATERIAL (
	CLASS_MATERIAL_CODE, CLASS_CODE, MATERIAL_NAME, MATERIAL_CONTENT
) VALUES (
	#{generatedCode}, #{classCode}, #{materialName}, #{materialContent}
)

mapper.select:
SELECT APPROVAL_STATUS
FROM CLASS
WHERE CLASS_CODE = #{classCode}
  AND OPERATOR_CODE = #{authorCode}

SELECT COUNT(*)
FROM CLASS
WHERE CLASS_CODE = #{classCode}
  AND OPERATOR_CODE = #{authorCode}
  AND STATUS IN ('모집중', '준비중')
  AND APPROVAL_STATUS = '승인'

mapper.update:
UPDATE CLASS
SET WRITE_DATE = SYSDATE
WHERE CLASS_CODE = #{classCode}
  AND OPERATOR_CODE = #{authorCode}
  AND STATUS = '준비중'
  AND APPROVAL_STATUS IN ('작성중', '수정중')

UPDATE CLASS
SET WRITE_DATE = WRITE_DATE
WHERE CLASS_CODE = #{classCode}
  AND OPERATOR_CODE = #{authorCode}
  AND STATUS IN ('모집중', '준비중')
  AND APPROVAL_STATUS = '승인'
